FILE: app/src/orbit-camera.ts
```ts
import {
  createArcRotateCamera,
  attachControl,
  enableArcRotateKeyboardControls,
} from "@babylonjs/lite";
import type { ArcRotateCamera, SceneContext } from "@babylonjs/lite";

export function createOrbitCamera(canvas: HTMLCanvasElement, scene: SceneContext): ArcRotateCamera {
  const camera = createArcRotateCamera(Math.PI / 2, Math.PI / 2, 10, { x: 0, y: 0, z: 0 });

  enableArcRotateKeyboardControls();
  attachControl(camera, canvas, scene, { keyboard: true });

  return camera;
}
```

I added `app/src/orbit-camera.ts` so it creates a 10-unit `ArcRotateCamera` looking at the origin, enables Babylon Lite’s arrow-key controls, and attaches the usual pointer controls via `attachControl` with `keyboard: true`. I was not sure whether root imports from `@babylonjs/lite` are the right import paths, whether a plain `{ x: 0, y: 0, z: 0 }` target object is accepted as `Vec3`, or whether both `enableArcRotateKeyboardControls()` and `attachControl({ keyboard: true })` are needed versus just one of them.
